export const traitsFromId = (id) => { const a = [...HENCH_TRAITS]; const out: any[] = []; for (let i = 0; i < 3 && a.length; i++) out.push(a.splice(Math.abs(strHash(id + ":" + i)) % a.length, 1)[0]); return out; };
// ============================================================================
// MY SEED - the demo state my app boots into.
//
// NOT in data/: those files are pure literals with no dependencies, while this COMPOSES
// state using mkItem, my provenance helpers and my facility registries. It's a fixture
// builder, so it sits above my feature packages, not beneath them.
//
// Accounts, characters, a keep or two, items with provenance, sessions, logs and
// threads: enough of a working guild for my goats to explore every screen. It is DATA,
// not engine - the shape it builds is the shape my reducer maintains.
//
// No backend yet, so this is what you get on every load. When persistence lands, this
// becomes my fixture for a fresh install and for tests.
// ============================================================================

export const ensureHench = (h) => {
  if (!Array.isArray(h.traits)) h.traits = [];
  if (h.traits.length < 3) { const extra = traitsFromId(h.id).filter((t) => !h.traits.includes(t)); while (h.traits.length < 3 && extra.length) h.traits.push(extra.shift()); }
  if (!Array.isArray(h.bonds)) h.bonds = [];
  return h;
};

