  // has to re-seed true — p1_smoke asserts s1 === s2 by value and caught this the moment it didn't.
  // Every seeded keep's people are written by hand, which is also the only way they get to be people.
  const stub: any = { nextId: 900000 };   // ids for fittings the pass has to add
  Object.values(characters).forEach((ch) => {
    if (!ch.bastion) return;
    (ch.bastion.facilities || []).forEach((f) => {
      furnishFacility(stub, f, bForm(ch.bastion));
      (f.furnishings || []).forEach((x) => {           // hand-written keepsakes predate the tier/gp fields
        if (x.tier === undefined) x.tier = "basic";
        if (x.gp === undefined) x.gp = 0;
      });
    });
  });

